import type { Register, ThemeSetArgs } from 'claude-code'

import { makeColors } from './make-colors.js'

// 霧光：莫蘭迪色系的未來感主題。
// 白天像晨霧裡的玻璃面板（霧灰綠底、霧湖藍強調），
// 夜晚像霧中的儀表板微光（深藍灰底、柔和的湖藍與灰紫）。
// 顏色都壓低彩度，對比留給文字，眼睛看久不累。

// 強調色：霧湖藍；紅、綠、黃保留原本的意思，只是調成莫蘭迪的灰調。
const ROLES = {
  accent: '#5a8f9a', // 霧湖藍
  danger: '#bb6157', // 乾燥玫瑰紅
  success: '#6f9d63', // 鼠尾草綠
  warning: { seed: '#c08f4a', fillShade: 450 }, // 赭黃，按鈕用深一階，不刺眼
  pro: '#8a78aa', // 灰紫
} as const

const { theme, problems } = makeColors({
  label: '霧光',
  roles: ROLES,
  light: {
    gray: {
      anchors: {
        'surface-0': '#e6eae8', // 頁面：霧灰綠
        'surface-1': '#edf0ee', // 卡片
        'surface-2': '#f5f7f5', // 面板
        'text-primary': '#243036', // 深石板藍
        'text-secondary': '#45525a',
        'text-muted': '#56636a',
      },
    },
    git: {
      added: '#4c7a45',
      removed: '#a85148',
      modified: '#946f2e',
      merged: '#735f93',
      closed: '#a85148',
      conflicting: '#9d5c2a',
      draft: '#5d6870',
    },
  },
  dark: {
    gray: {
      anchors: {
        'surface-0': '#1a2023', // 頁面：夜霧藍灰
        'surface-1': '#20272a',
        'surface-2': '#262e31',
        'surface-3': '#293134', // 選單：貼近頁面，灰字才看得清楚
        'text-primary': '#e5e9e6', // 帶一點綠的米白，不用純白
        'text-secondary': '#bec6c4',
        'text-muted': '#99a3a2',
      },
    },
    // 深色模式的綠字提亮一階，在面板上才讀得清楚
    roles: { ...ROLES, success: { seed: '#6f9d63', stops: { 400: '#8fbb80' } } },
    git: {
      added: '#98bb8a',
      removed: '#e0968d',
      modified: '#d8b47c',
      merged: '#bbaad6',
      closed: '#e0968d',
      conflicting: '#e0a273',
      draft: '#a3adb2',
    },
  },
})

// 動態背景「光絲流」：兩束極細光絲交織。主束 22 條往左流，副束 12 條往右流、波長是主束的 2/3、比較淡；
// 左右兩端淡出，再加稀疏的極細粒子分三層由左往右漂（近的快、遠的慢）。
// 省資源：「動一陣、停一陣」。所有東西一起緩緩流動 20 秒，再一起完全靜止 20 秒；一輪 4 次、160 秒。
// 用 SVG 內建的 <animateTransform>（SMIL）而不是 CSS 動畫：CSS 動畫只要還在跑，就算沒動也會每格重畫；
// SMIL 每段播完就凍結，靜止時畫面完全不重畫、不耗資源。流動時同一束分組各走略不同的距離，形狀會微微變化，
// 每一輪每組剛好走完整數個波長，所以無限循環、接縫對齊。
// 顏色跟著系統的淺色、深色切換。注意：SMIL 不理會系統的「減少動態效果」設定。
// 這段 SVG 由 tools/gen-silk.mjs 產生，要改請改產生器的參數再重新產生，不要手改。
