// 毛玻璃只輕微模糊（3）、蓋一半：光絲和粒子透得出來，經過文字後面時又會被柔化，不干擾閱讀。
const LOOK: ThemeSetArgs = {
  colors: theme,
  backdrop: { scene: SCENE_NAME, glass: { blur: 3, opacity: 0.5 } },
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    // 開發時用：桌面版若整套不畫，會跳出原因
    const unpainted = problems.find(line => line.startsWith("Desktop won't paint"))

    if (unpainted !== undefined) {
      $.ui.toast(unpainted)
    }
    // 剛啟動時桌面版常常還沒連上，這時 isDrawn 會是 false，
    // 但主題會保留，等桌面版連上就畫，所以不用在狀態列顯示原因。
    await $.theme.set(LOOK)

    return next(e)
  })

  on('ui.render', { component: 'Backdrop' }, ($, e, next) => {
    if (e.props.plugin !== $.plugin.name || e.props.scene !== SCENE_NAME) {
      return next(e)
    }
    if (e.surface !== 'desktop' && e.surface !== 'mobile') {
      return next(e)
    }
    const { Svg } = $.ui.resolve(e)

    return (
      <Svg
        source={SCENE_SVG}
        alt="彩色細光絲像絲綢一樣橫向流動，稀疏的細小粒子由左往右漂"
        isInteractive
      />
    )
  })
}
